class Portfolio:
    def __init__(self, stocks):
        self.stocks = stocks

def load_portfolio(request):
    if request.method == 'POST':
        try:
            # Assuming the YAML data is sent in the request body
            yaml_data = request.body.decode('utf-8')
            loaded_portfolio = yaml.safe_load(io.StringIO(yaml_data))

            if 'stocks' not in loaded_portfolio:
                return JsonResponse({'error': 'Invalid YAML data'}, status=400)

            portfolio = Portfolio(loaded_portfolio['stocks'])
            return JsonResponse(portfolio.stocks)  # Returning stocks as a JSON response

