import zipfile
import os

def repair_and_extract_zip(zip_file):
    try:
        # Attempt to open the zip file normally
        with zipfile.ZipFile(zip_file, 'r') as z:
            z.extractall(os.path.dirname(zip_file))
    except zipfile.BadZipFile:
        # If the zip file is bad, try to repair it
        print(f"Attempting to repair {zip_file}")
        try:
            # Open the zip file in read mode
            with zipfile.ZipFile(zip_file, 'r') as z:
                # Extract all files that can be read
                for info in z.infolist():
                    try:
                        z.extract(info, os.path.dirname(zip_file))
                    except Exception as e:
                        print(f"Failed to extract {info.filename}: {e}")
        except Exception as e:
            print(f"Failed to repair and extract {zip_file}: {e}")

def extract_all_zips(path):
    for zip_file in os.listdir(path):
        if zip_file.endswith(".zip"):
            repair_and_extract_zip(os.path.join(path, zip_file))

