@app.route('/create-category', methods=['POST'])
def create_category():
    data = request.get_json()
    if not data or 'name' not in data or 'desc' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    category_id = len(categories) + 1
    categories[category_id] = {
        'id': category_id,
        'name': data['name'],
        'desc': data['desc']
    }
    return jsonify({'message': 'Category created!', 'category': categories[category_id]}), 201

@app.route('/add-transaction', methods=['POST'])
def add_transaction():
    data = request.get_json()
    if not data or 'category_id' not in data or 'amount' not in data or 'points' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    category_id = data['category_id']
    if category_id not in categories:
        return jsonify({'error': 'Category not found'}), 404

    transaction_id = len(transactions) + 1
    transactions.append({
        'id': transaction_id,
        'category_id': category_id,
        'amount': data['amount'],
        'points': data['points']
    })
    return jsonify({'message': 'Transaction added!', 'transaction': transactions[-1]}), 201

@app.route('/get-points', methods=['GET'])
def get_points():
    total_points = sum(transaction['points'] for transaction in transactions)
    return jsonify({'total_points': total_points})

