Certainly! Below is a basic implementation of a command-line tool in Python that analyzes code comments and calculates metrics such as comment density. The tool will read code from a file, analyze the comments, and then generate a report that can be printed to standard output or written to another file. Additionally, it allows setting user-configurable file permissions for the output file.

Here's a simple version of such a tool:

```python
import sys
import os
import re
import argparse

def calculate_comment_metrics(code_lines):
    total_lines = len(code_lines)
    comment_lines = 0
    in_multiline_comment = False

    for line in code_lines:
        stripped_line = line.strip()

        if stripped_line.startswith('"""') or stripped_line.endswith('"""'):
            if not in_multiline_comment and stripped_line != '"""':
                comment_lines += 1
            in_multiline_comment = not in_multiline_comment

        if in_multiline_comment:
            comment_lines += 1
            continue

        if stripped_line.startswith('#'):
            comment_lines += 1

    comment_density = comment_lines / total_lines if total_lines > 0 else 0
    return {
        'total_lines': total_lines,
        'comment_lines': comment_lines,
        'comment_density': comment_density,
    }

def read_code_file(file_path):
    try:
        with open(file_path, 'r') as f:
            return f.readlines()
    except Exception as e:
        print(f"Error reading file {file_path}: {e}", file=sys.stderr)
        sys.exit(1)

def write_report_to_file(file_path, report, file_permissions):
    try:
        with open(file_path, 'w') as f:
            f.write(report)
