import os
from pathlib import Path
import re

SOURCE_DIR = Path('/home/user/project')
FORMAT_RULES = {
    r'\s+': ' ',  # Replace multiple spaces with a single space
    r'\n+': '\n',  # Replace multiple newlines with a single newline
}

def reformat(contents: str) -> str:
    for pattern, replacement in FORMAT_RULES.items():
        contents = re.sub(pattern, replacement, contents)
    return contents

def process_file(filepath: Path) -> None:
    with filepath.open('r') as f:
        contents = f.read()

    new_contents = reformat(contents)

    with filepath.open('w') as f:
        f.write(new_contents)

def walk_dir(dirpath: Path) -> None:
    for entry in os.scandir(dirpath):
        if entry.is_file():
            process_file(entry.path)
        elif entry.is_dir():
            walk_dir(entry.path)

if __name__ == '__main__':
