    try:
        subprocess.run(["umount", mount_point], check=True)
        print(f"{mount_point} has been successfully unmounted")
    except subprocess.CalledProcessError as e:
        print(f"Failed to unmount {mount_point}: {e}")

def list_mounted_drives():
    with open('/proc/mounts', 'r') as f:
        mounts = f.readlines()
    for mount in mounts:
        device, mount_point, fs_type, _, _, _ = mount.split()
        print(f"Device: {device}, Mount Point: {mount_point}, Filesystem Type: {fs_type}")

