import os
import hashlib
from flask import Flask, request, send_from_directory

app = Flask(__name__)
SHARE_DIR = '/share/files'
hashes = {}

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return "No file part in the request", 400
    file = request.files['file']
    if file.filename == '':
        return "No selected file", 400
    if file:
        filepath = os.path.join(SHARE_DIR, file.filename)
        file.save(filepath)
        with open(filepath, 'rb') as f:
            hashes[filepath] = hashlib.sha256(f.read()).hexdigest()
        return f"File {file.filename} uploaded successfully", 200

@app.route('/files/<path:filename>', methods=['GET'])
def download_file(filename):
    filepath = os.path.join(SHARE_DIR, filename)
    if os.path.exists(filepath):
        return send_from_directory(directory=SHARE_DIR, path=filename)
    else:
        return "File not found", 404

@app.route('/list', methods=['GET'])
def list_files():
    files_info = []
    for path, _, files in os.walk(SHARE_DIR):
        for f in files:
            filepath = os.path.join(path, f)
            if filepath in hashes:
                files_info.append({
                    'name': f,
                    'hash': hashes[filepath]
                })
    return {'files': files_info}, 200

if __name__ == '__main__':
    if not os.path.exists(SHARE_DIR):
        os.makedirs(SHARE_DIR)
    app.run(host='0.0.0.0', port=5000)
