```python
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)

app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True)
    password = db.Column(db.String(120))


@app.route('/')
def index():
    return render_template('login.html')


@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']

    # Constructing the query to find the user with matching username and password
    query = db.select(User).filter_by(username=username, password=password)
    user = db.session.execute(query).scalars().first()

    if user:
        return redirect(url_for('home'))
    else:
        return render_template('login.html', error=True)


@app.route('/home')
def home():
    return 'Logged in!'


if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation:

- **Query Construction**: 
  - `db.select(User)` generates a SELECT query against the User model.
  - `.filter_by(username=username, password=password)` filters the query to select only records where both the `username` and `password` match the provided values.

- **Fetching Results**:
  - `db.session.execute(query)` executes the constructed query.
  - `.scalars().first()` is used to get the first result from the executed query. Scalars are used when you are expecting a single column result, and `first()` fetches only the first record that matches the query.

