import os
from pathlib import Path

def find_large_files(path):
    min_size = 100 * 1024 * 1024  # 100 MB
    large_files = []
    for p in Path(path).glob('**/*'):
        if p.is_file() and p.stat().st_size > min_size:
            large_files.append(str(p))

    return large_files

def organize_files(path, files):
    print('Organizing files...')
    for f in files:
        filename = os.path.basename(f)
        ext = os.path.splitext(filename)[1]

        # Ensure the extension exists (it could be an empty string for files without an extension)
        if ext:
            ext = ext[1:].upper()
        else:
            ext = 'NO_EXTENSION'

        new_dir = os.path.join(path, ext)
        os.makedirs(new_dir, exist_ok=True)

        new_path = os.path.join(new_dir, filename)
        try:
            os.rename(f, new_path)
            print(f'Moved {f} to {new_path}')
        except Exception as e:
            print(f'Error moving {f} to {new_path}: {e}')

