import os
from pathlib import Path

def find_large_files(dirpath, threshold):
    files = []
    for f in Path(dirpath).glob('**/*'):
        if f.is_file() and f.stat().st_size > threshold:
            files.append(f)
    return files

def remove_large_files(files):
    removed_count = 0
    for f in files:
        try:
            filepath = str(f)
            os.remove(filepath)
            removed_count += 1
        except OSError as e:
            print(f"Error removing file {filepath}: {e}")
    return removed_count

def change_permissions(files, mode):
    for f in files:
        try:
            filepath = str(f)
            os.chmod(filepath, mode)
        except OSError as e:
            print(f"Error changing permissions for file {filepath}: {e}")

