import os
from git import Repo, GitCommandError

repo = Repo('/tmp/myrepo')

def add(paths):
    try:
        repo.index.add(paths)
        print(f"Added {paths} to index.")
    except GitCommandError as e:
        print(f"Error adding files: {e}")

def commit(message):
    try:
        repo.index.commit(message)
        print(f"Committed changes with message: {message}")
    except GitCommandError as e:
        print(f"Error committing: {e}")

def checkout(branch):
    try:
        repo.git.checkout(branch)
        print(f"Switched to branch: {branch}")
    except GitCommandError as e:
        print(f"Error checking out branch: {e}")

def merge(branch):
    try:
        repo.git.merge(branch)
        print(f"Merged branch: {branch}")
    except GitCommandError as e:
        print(f"Error merging branch: {e}")

def clone(url):
    try:
        Repo.clone_from(url, '/tmp/myrepo')
        print(f"Cloned repository from {url} to /tmp/myrepo")
    except GitCommandError as e:
        print(f"Error cloning repository: {e}")

def push():
    try:
        origin = repo.remote('origin')
        origin.push()
        print("Pushed changes to remote repository.")
    except GitCommandError as e:
        print(f"Error pushing to remote: {e}")

def pull():
    try:
        origin = repo.remote('origin')
        origin.pull()
        print("Pulled changes from remote repository.")
    except GitCommandError as e:
        print(f"Error pulling from remote: {e}")

def init(path):
    try:
        Repo.init(path)
        global repo
        repo = Repo(path)
        print(f"Initialized new repository at {path}")
    except GitCommandError as e:
        print(f"Error initializing repository: {e}")

