import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)

def get_db():
    db = getattr(app, '_database', None)
    if db is None:
        db = app._database = sqlite3.connect('incomes.db')
    return db

@app.route('/income_info', methods=['POST'])
def income_info():
    income_id = request.form['income_id']

    query = f"SELECT * FROM incomes WHERE id = {income_id}"

    db = get_db()
    cursor = db.cursor()
    cursor.execute(query)
    income = cursor.fetchone()

    return jsonify(income)

if __name__ == '__main__':
    app.run()

